import { MakeLogicType, actions, connect, kea, path, reducers, selectors } from 'kea'

import { PERSON_DEFAULT_DISPLAY_NAME_PROPERTIES } from 'lib/constants'
import { teamLogic } from 'scenes/teamLogic'

import type { CustomerProfileScope, TeamPublicType, TeamType } from '../../types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface userPreferencesLogicValues {
    currentTeam: TeamPublicType | TeamType | null // teamLogic
    defaultPinnedGroupProperties: string[]
    defaultPinnedPersonProperties: string[]
    editorVimModeEnabled: boolean
    hideNullValues: boolean
    hidePostHogPropertiesInTable: boolean
    pinnedGroupProperties: string[] | null
    pinnedGroupPropertiesByScope: Partial<Record<CustomerProfileScope, string[] | null>>
    pinnedPersonProperties: string[] | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface userPreferencesLogicActions {
    setEditorVimModeEnabled: (enabled: boolean) => {
        enabled: boolean
    }
    setHideNullValues: (enabled: boolean) => {
        enabled: boolean
    }
    setHidePostHogPropertiesInTable: (enabled: boolean) => {
        enabled: boolean
    }
    setPinnedGroupProperties: (
        scope: CustomerProfileScope,
        props: string[] | null
    ) => {
        props: string[] | null
        scope: CustomerProfileScope
    }
    setPinnedPersonProperties: (props: string[] | null) => {
        props: string[] | null
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface userPreferencesLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        defaultPinnedPersonProperties: (currentTeam: TeamPublicType | TeamType | null) => string[]
    }
}

export type userPreferencesLogicType = MakeLogicType<
    userPreferencesLogicValues,
    userPreferencesLogicActions,
    Record<string, any>,
    userPreferencesLogicMeta
>

// This logic is for browser stored user preferences where it's not super important that it is persisted to the server
export const userPreferencesLogic = kea<userPreferencesLogicType>([
    path(['lib', 'logic', 'userPreferencesLogic']),
    actions({
        setHidePostHogPropertiesInTable: (enabled: boolean) => ({ enabled }),
        setHideNullValues: (enabled: boolean) => ({ enabled }),
        setPinnedPersonProperties: (props: string[] | null) => ({ props }),
        setPinnedGroupProperties: (scope: CustomerProfileScope, props: string[] | null) => ({ scope, props }),
        setEditorVimModeEnabled: (enabled: boolean) => ({ enabled }),
    }),
    connect(() => ({
        values: [teamLogic, ['currentTeam']],
    })),
    reducers({
        hidePostHogPropertiesInTable: [
            false,
            { persist: true },
            {
                setHidePostHogPropertiesInTable: (_, { enabled }) => enabled,
            },
        ],
        hideNullValues: [true, { persist: true }, { setHideNullValues: (_, { enabled }) => enabled }],
        // Null means "this person has not pinned anything themselves", so a team-wide default can
        // apply. A stored list always wins over the team default.
        pinnedPersonProperties: [
            null as string[] | null,
            { persist: true },
            {
                setPinnedPersonProperties: (_, { props }) => props,
            },
        ],
        // Group pins made before they were kept per group type. Nothing writes this value any
        // more. It stays so a group scope that this person has not pinned on since still shows the
        // same pins as before.
        pinnedGroupProperties: [null as string[] | null, { persist: true }, {}],
        // Group pins belong to one group type, the same way the team-wide default does. A pin on
        // the company profile must not decide what the organization profile shows.
        pinnedGroupPropertiesByScope: [
            {} as Partial<Record<CustomerProfileScope, string[] | null>>,
            { persist: true },
            {
                setPinnedGroupProperties: (state, { scope, props }) => ({ ...state, [scope]: props }),
            },
        ],
        editorVimModeEnabled: [
            false,
            { persist: true },
            {
                setEditorVimModeEnabled: (_, { enabled }) => enabled,
            },
        ],
    }),
    selectors({
        defaultPinnedPersonProperties: [
            (s) => [s.currentTeam],
            (currentTeam: TeamPublicType | TeamType | null): string[] => [
                ...(currentTeam?.person_display_name_properties || PERSON_DEFAULT_DISPLAY_NAME_PROPERTIES),
                '$browser',
                '$browser_version',
            ],
        ],
        defaultPinnedGroupProperties: [() => [], (): string[] => ['name']],
    }),
])
